begin;
create function pg_temp.social_assert(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Social check failed: %',label;end if;perform set_config('lumo.social.checks',(coalesce(nullif(current_setting('lumo.social.checks',true),''),'0')::integer+1)::text,true);end $$;
do $test$
#variable_conflict use_variable
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();merchant uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();a2sid uuid:=gen_random_uuid();bsid uuid:=gen_random_uuid();csid uuid:=gen_random_uuid();msid uuid:=gen_random_uuid();wallet_a uuid;wallet_b uuid;wallet_c uuid;j uuid;other_j uuid;req uuid:=gen_random_uuid();req2 uuid:=gen_random_uuid();req3 uuid:=gen_random_uuid();suffix text:=substr(replace(gen_random_uuid()::text,'-',''),1,10);ap jsonb;bp jsonb;cp jsonb;mp jsonb;out jsonb;out2 jsonb;payload jsonb;friend jsonb;seen text;pid text:='social-partner-'||gen_random_uuid()::text;contract jsonb:='{}'::jsonb;notification text;case_id uuid:=gen_random_uuid();nid uuid;u uuid;k integer;
begin
 insert into auth.users(id,aud,role,email,created_at,raw_app_meta_data) select id,'authenticated','authenticated',kind||suffix||'@example.test',now(),'{"lumo_pilot":true}'::jsonb from(values(a,'sociala'),(b,'socialb'),(c,'socialc'),(merchant,'socialmerchant'))v(id,kind);
 insert into auth.sessions(id,user_id,created_at) values(sid,a,now()),(a2sid,a,now()),(bsid,b,now()),(csid,c,now()),(msid,merchant,now());
 insert into lumo_private.profiles(user_id,handle,display_name,pin_hash) values(a,'sa_'||suffix,'Social A','fixture'),(b,'sb_'||suffix,'Social B','fixture'),(c,'sc_'||suffix,'Social C','fixture'),(merchant,'sm_'||suffix,'Social merchant','fixture');
 insert into lumo_private.approved_profiles(user_id,personal_account) values(a,true),(b,true),(c,true),(merchant,false);
 insert into lumo_private.accounts(owner_user_id,kind) values(a,'consumer') returning id into wallet_a;
 insert into lumo_private.accounts(owner_user_id,kind) values(b,'consumer') returning id into wallet_b;
 insert into lumo_private.accounts(owner_user_id,kind) values(c,'consumer') returning id into wallet_c;
 insert into lumo_private.accounts(owner_user_id,kind) values(merchant,'consumer');
 ap:=jsonb_build_object('actor',a,'session',sid);bp:=jsonb_build_object('actor',b,'session',bsid);cp:=jsonb_build_object('actor',c,'session',csid);mp:=jsonb_build_object('actor',merchant,'session',msid);
 perform set_config('request.jwt.claims','{"role":"anon"}',true);out:=public.lumo_social('friends.list',ap);perform pg_temp.social_assert(out->>'code'='FORBIDDEN','anonymous role cannot invoke social RPC');
 perform set_config('request.jwt.claims','{"role":"authenticated"}',true);out:=public.lumo_social('friends.list',ap);perform pg_temp.social_assert(out->>'code'='FORBIDDEN','authenticated role cannot directly invoke privileged RPC');
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 out:=public.lumo_social('friends.list',mp);perform pg_temp.social_assert(out->>'code'='ACCOUNT_REQUIRED','merchant-only identity cannot use consumer social data');
 out:=public.lumo_social('friends.list',ap);perform pg_temp.social_assert(out#>'{data,friends}'='[]'::jsonb,'new account starts without invented friends');
 payload:=ap||jsonb_build_object('recipientId',b,'listName','Circle','requestId',req);
 out:=public.lumo_social('friends.save',payload);perform pg_temp.social_assert(out->>'ok'='true' and out#>>'{data,record,userId}'=b::text and out#>>'{data,record,revision}'='1','saved friend stable identity and initial revision');friend:=out#>'{data,record}';contract:=contract||jsonb_build_object('friendsAvailable',jsonb_build_object('friends',jsonb_build_array(friend),'limit',200));
 perform pg_temp.social_assert(not(friend ? 'phone') and not(friend ? 'balance') and not(friend ? 'activity') and friend->>'available'='true','friend card excludes phone and financial/presence data');
 out:=public.lumo_social('friends.save',payload);perform pg_temp.social_assert(out#>>'{data,duplicate}'='true','same-request retry idempotent');
 out:=public.lumo_social('friends.save',(payload-'session')||jsonb_build_object('session',a2sid));perform pg_temp.social_assert(out#>>'{data,duplicate}'='true','same owner retry works across live sessions');
 out:=public.lumo_social('friends.save',payload||jsonb_build_object('listName','Crew'));perform pg_temp.social_assert(out->>'code'='IDEMPOTENCY_CONFLICT','request UUID cannot change list or target');
 out:=public.lumo_social('friends.list',bp);perform pg_temp.social_assert(out#>'{data,friends}'='[]'::jsonb,'saved friendship is private and not reciprocated');
 out:=public.lumo_social('friends.save',ap||jsonb_build_object('recipientId',a,'listName','Circle','requestId',gen_random_uuid()));perform pg_temp.social_assert(out->>'code'='SELF_FRIEND','cannot add own account');
 out:=public.lumo_social('friends.save',ap||jsonb_build_object('recipientId',merchant,'listName','Circle','requestId',gen_random_uuid()));perform pg_temp.social_assert(out->>'code'='RECIPIENT_NOT_FOUND','merchant-only recipient rejected');
 out:=public.lumo_social('friends.save',ap||jsonb_build_object('recipientId',gen_random_uuid(),'listName','Circle','requestId',gen_random_uuid()));perform pg_temp.social_assert(out->>'code'='RECIPIENT_NOT_FOUND','nonexistent recipient rejected');
 out:=public.lumo_social('friends.save',ap||jsonb_build_object('recipientId',b,'listName','Crew','requestId',gen_random_uuid()));perform pg_temp.social_assert(out->>'code'='REVISION_CONFLICT','existing friend cannot be overwritten without current revision');
 payload:=ap||jsonb_build_object('recipientId',b,'listName','Study Buddies','requestId',req2,'revision',1);
 out:=public.lumo_social('friends.save',payload);perform pg_temp.social_assert(out#>>'{data,record,revision}'='2' and out#>>'{data,record,listName}'='Study Buddies','list edit increments revision');
 out:=public.lumo_social('friends.save',payload||jsonb_build_object('listName','Crew','requestId',gen_random_uuid()));perform pg_temp.social_assert(out->>'code'='REVISION_CONFLICT','second writer with old revision cannot win');
 out:=public.lumo_social('friends.remove',bp||jsonb_build_object('recipientId',b,'requestId',gen_random_uuid(),'revision',2));perform pg_temp.social_assert(out->>'code'='SELF_FRIEND','another account cannot remove owner friend');
 out:=public.lumo_social('friends.remove',cp||jsonb_build_object('recipientId',b,'requestId',gen_random_uuid(),'revision',2));perform pg_temp.social_assert(out->>'code'='NOT_FOUND','cross-owner friend removal blocked');
 payload:=ap||jsonb_build_object('recipientId',b,'requestId',req3,'revision',2);
 out:=public.lumo_social('friends.remove',payload);perform pg_temp.social_assert(out#>>'{data,removed}'='true','friend removed');
 out:=public.lumo_social('friends.save',ap||jsonb_build_object('recipientId',b,'listName','Circle','requestId',req));perform pg_temp.social_assert(out#>>'{data,duplicate}'='true','late old save returns historical confirmation only');
 out:=public.lumo_social('friends.list',ap);perform pg_temp.social_assert(out#>'{data,friends}'='[]'::jsonb,'late save retry cannot resurrect removed friend');
 out:=public.lumo_social('friends.remove',payload);perform pg_temp.social_assert(out#>>'{data,duplicate}'='true','remove retry is idempotent');
 out:=public.lumo_social('friends.save',ap||jsonb_build_object('recipientId',b,'listName','Lumo Squad','requestId',gen_random_uuid()));perform pg_temp.social_assert(out#>>'{data,record,revision}'='4','fresh add after removal advances tombstone revision');
 out:=public.lumo_social('friends.remove',payload||jsonb_build_object('requestId',gen_random_uuid()));perform pg_temp.social_assert(out->>'code'='REVISION_CONFLICT','stale remove cannot delete newly re-added recipient');
 update lumo_private.profiles set handle='renamed_'||suffix,display_name='Renamed Social B' where user_id=b;
 out:=public.lumo_social('friends.list',ap);perform pg_temp.social_assert(out#>>'{data,friends,0,userId}'=b::text and out#>>'{data,friends,0,name}'='Renamed Social B','friend follows stable identity after handle change');
 update lumo_private.accounts set status='closed' where id=wallet_b;
 out:=public.lumo_social('friends.list',ap);perform pg_temp.social_assert(out#>>'{data,friends,0,available}'='false' and out#>>'{data,friends,0,handle}'='' and out#>>'{data,friends,0,name}'='Unavailable Lumo account','closed recipient is clearly unavailable with generic display');contract:=contract||jsonb_build_object('friendsUnavailable',out->'data');
 out:=public.lumo_social('friends.save',ap||jsonb_build_object('recipientId',b,'listName','Circle','revision',4,'requestId',gen_random_uuid()));perform pg_temp.social_assert(out->>'code'='RECIPIENT_NOT_FOUND','closed recipient cannot be saved anew');
 out:=public.lumo_social('friends.remove',ap||jsonb_build_object('recipientId',b,'revision',4,'requestId',gen_random_uuid()));perform pg_temp.social_assert(out#>>'{data,removed}'='true','unavailable friend stays removable');
 update lumo_private.accounts set status='active' where id=wallet_b;
 u:=gen_random_uuid();insert into auth.users(id,aud,role,email) values(u,'authenticated','authenticated','missing-profile-'||suffix||'@example.test');insert into lumo_private.social_friends(owner_id,recipient_id,list_name) values(a,u,'Circle');
 out:=public.lumo_social('friends.list',ap);perform pg_temp.social_assert(out#>>'{data,friends,0,userId}'=u::text and out#>>'{data,friends,0,available}'='false' and out#>>'{data,friends,0,name}'='Unavailable Lumo account','missing recipient profile still returns removable unavailable friend');
 delete from lumo_private.social_friends where owner_id=a and recipient_id=u;
 insert into lumo_private.journals(type,amount,payer_account_id,payee_account_id,actor_user_id) values('transfer',100,wallet_a,wallet_b,a) returning id into j;
 insert into lumo_private.entries(journal_id,account_id,amount) values(j,wallet_a,-100),(j,wallet_b,100);
 insert into lumo_private.approved_postings(journal_id,user_id,transaction_id,metadata) values(j,a,'social-transaction-'||suffix,'{}');
 insert into lumo_private.journals(type,amount,payer_account_id,payee_account_id,actor_user_id) values('transfer',100,wallet_b,wallet_c,b) returning id into other_j;
 insert into lumo_private.entries(journal_id,account_id,amount) values(other_j,wallet_b,-100),(other_j,wallet_c,100);
 out:=public.lumo_social('notifications.list',ap);perform pg_temp.social_assert(out#>>'{data,total}'='1' and out#>>'{data,unreadCount}'='1','payment appears exactly once only in involved account feed');
 perform pg_temp.social_assert(out#>>'{data,notifications,0,target,id}'='social-transaction-'||suffix and out#>>'{data,notifications,0,target,kind}'='activity','notification opens own transaction identity');
 perform pg_temp.social_assert(not((out#>'{data,notifications,0}') ? 'amount'),'notification does not expose amount in the center');
 notification:='payment:'||j::text;
 out:=public.lumo_social('notifications.read',cp||jsonb_build_object('notificationId',notification));perform pg_temp.social_assert(out->>'code'='NOT_FOUND','unrelated account cannot acknowledge another person payment');
 out:=public.lumo_social('notifications.read',ap||jsonb_build_object('notificationId',notification));seen:=out#>>'{data,readAt}';perform pg_temp.social_assert(out->>'ok'='true' and seen is not null,'notification read recorded');
 out:=public.lumo_social('notifications.read',ap||jsonb_build_object('notificationId',notification));perform pg_temp.social_assert(out#>>'{data,readAt}'=seen,'read retry retains original timestamp');
 out:=public.lumo_social('notifications.list',(ap-'session')||jsonb_build_object('session',a2sid));perform pg_temp.social_assert(out#>>'{data,unreadCount}'='0','read state shared between owner sessions');
 out:=public.lumo_social('notifications.list',bp);perform pg_temp.social_assert(out#>>'{data,unreadCount}'='2','owner read does not change recipient unread state');
 insert into lumo_private.approved_partners(id,owner_user_id,partner_user_id,revision,kind,state) values(pid,a,b,1,'initial',jsonb_build_object('invitation',jsonb_build_object('status','accepted','code','123456','partner',jsonb_build_object('phone','0249999999'),'boxName','Private goal'),'ownerName','Social A'));
 out:=public.lumo_social('notifications.list',bp);perform pg_temp.social_assert(out#>>'{data,total}'='3' and position('123456' in out::text)=0 and position('0249999999' in out::text)=0 and position('Private goal' in out::text)=0,'partner feed omits code, phone, private goal');
 out:=public.lumo_social('notifications.read',bp||jsonb_build_object('notificationId','partner:'||pid||':1'));perform pg_temp.social_assert(out->>'ok'='true','current partner notification can be read');
 update lumo_private.approved_partners set revision=2,updated_at=clock_timestamp() where id=pid;
 out:=public.lumo_social('notifications.read',bp||jsonb_build_object('notificationId','partner:'||pid||':1'));perform pg_temp.social_assert(out->>'code'='NOT_FOUND','stale partner revision cannot acknowledge new event');
 out:=public.lumo_social('notifications.list',bp);perform pg_temp.social_assert(out#>>'{data,unreadCount}'='3','new partner revision becomes unread');
 out:=public.lumo_social('notifications.list',cp);perform pg_temp.social_assert(out#>>'{data,total}'='1','unrelated account cannot see partner event');
 insert into lumo_private.admin_cases(id,subject,customer_id) values(case_id,'Synthetic social support update',a);
 insert into lumo_private.case_notifications(case_id,case_revision,recipient_id,audience,title,body,case_status) values(case_id,1,a,'consumer','Support update','Synthetic safe customer reply','open') returning id into nid;
 out:=public.lumo_social('notifications.read',ap||jsonb_build_object('notificationId','support:'||nid::text));perform pg_temp.social_assert(out->>'ok'='true' and (select read_at is not null from lumo_private.case_notifications where id=nid),'unified support read synchronizes original inbox');
 update lumo_private.case_notifications set read_at=null where id=nid;delete from lumo_private.social_notification_reads where owner_id=a and notification_id='support:'||nid::text;
 update lumo_private.case_notifications set read_at=clock_timestamp() where id=nid;
 out:=public.lumo_social('notifications.list',ap);perform pg_temp.social_assert(out#>>'{data,unreadCount}'='1','reading existing support inbox updates unified unread count');contract:=contract||jsonb_build_object('ownerNotifications',out->'data');out:=public.lumo_social('notifications.list',bp);contract:=contract||jsonb_build_object('partnerNotifications',out->'data');perform set_config('lumo.social.contract_fixture',contract::text,true);
 out:=public.lumo_social('notifications.list',ap||'{"page":2,"pageSize":1}'::jsonb);perform pg_temp.social_assert(jsonb_array_length(out#>'{data,notifications}')=1 and out#>>'{data,total}'='3' and out#>>'{data,hasMore}'='true','notification paging preserves total and bounded page');
 for payload in select value from jsonb_array_elements('[{"page":0},{"pageSize":51},{"pageSize":-1}]'::jsonb) loop out:=public.lumo_social('notifications.list',ap||payload);perform pg_temp.social_assert(out->>'code'='INVALID_INPUT','invalid paging rejected');end loop;
 update auth.sessions set not_after=now()-interval '1 minute' where id=sid;out:=public.lumo_social('friends.list',ap);perform pg_temp.social_assert(out->>'code'='SESSION_REVOKED','expired session cannot access social data');
 out:=public.lumo_social('friends.list',ap||jsonb_build_object('session',bsid));perform pg_temp.social_assert(out->>'code'='SESSION_REVOKED','valid session belonging to another account rejected');
 ap:=ap||jsonb_build_object('session',a2sid);
 update auth.users set banned_until=now()+interval '1 hour' where id=a;out:=public.lumo_social('friends.list',ap);perform pg_temp.social_assert(out->>'code'='SESSION_REVOKED','banned account denied');update auth.users set banned_until=null where id=a;
 update auth.users set deleted_at=now() where id=a;out:=public.lumo_social('friends.list',ap);perform pg_temp.social_assert(out->>'code'='SESSION_REVOKED','deleted account denied despite unexpired token');update auth.users set deleted_at=null where id=a;
 update auth.users set is_anonymous=true where id=a;out:=public.lumo_social('friends.list',ap);perform pg_temp.social_assert(out->>'code'='SESSION_REVOKED','anonymous authenticated identity denied');update auth.users set is_anonymous=false where id=a;
 perform pg_temp.social_assert((select count(*)=3 from pg_class t join pg_namespace n on n.oid=t.relnamespace where n.nspname='lumo_private' and t.relname in('social_friends','social_mutations','social_notification_reads') and t.relrowsecurity),'RLS enabled for all private social tables');
 perform pg_temp.social_assert(not has_function_privilege('authenticated','public.lumo_social(text,jsonb)','execute') and not has_function_privilege('anon','public.lumo_social(text,jsonb)','execute') and has_function_privilege('service_role','public.lumo_social(text,jsonb)','execute'),'RPC only service executable');
 perform pg_temp.social_assert(not has_function_privilege('service_role','lumo_private.social_notification_feed(uuid)','execute') and not has_function_privilege('authenticated','lumo_private.social_friend_json(lumo_private.social_friends)','execute'),'private helpers not directly executable');
 perform pg_temp.social_assert(not has_table_privilege('authenticated','lumo_private.social_friends','select') and not has_table_privilege('service_role','lumo_private.social_notification_reads','insert'),'direct private table grants revoked');
 -- Bound limits are validated without creating any durable user or money data.
 for k in 1..200 loop u:=gen_random_uuid();insert into auth.users(id,aud,role,email) values(u,'authenticated','authenticated','sf'||replace(u::text,'-','')||'@example.test');insert into lumo_private.social_friends(owner_id,recipient_id,list_name) values(a,u,'Circle');end loop;
 out:=public.lumo_social('friends.save',ap||jsonb_build_object('recipientId',c,'listName','Circle','requestId',gen_random_uuid()));perform pg_temp.social_assert(out->>'code'='FRIEND_LIMIT','active friend count limit enforced under owner lock');
 insert into lumo_private.social_mutations(owner_id,request_id,payload,response) select a,gen_random_uuid(),'{}'::jsonb,'{}'::jsonb from generate_series(1,100);
 out:=public.lumo_social('friends.save',ap||jsonb_build_object('recipientId',c,'listName','Circle','requestId',gen_random_uuid()));perform pg_temp.social_assert(out->>'code'='RATE_LIMITED','distinct mutation volume bounded');
 out:=public.lumo_social('friends.save',ap||jsonb_build_object('recipientId',b,'listName','Circle','requestId',req));perform pg_temp.social_assert(out#>>'{data,duplicate}'='true','successful retry remains available even after write-rate bound');
 delete from auth.sessions where id=a2sid;out:=public.lumo_social('notifications.list',ap);perform pg_temp.social_assert(out->>'code'='SESSION_REVOKED','revoked Auth session cannot list notifications');
end $test$;
select current_setting('lumo.social.checks')::integer social_checks,current_setting('lumo.social.contract_fixture')::jsonb contract_fixture;
rollback;
